 public async Task<ConstruccionDetalleDto?>ObtenerAsync(long id,AlcanceConstruccion a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_construccion_leer_por_id");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;var x=new ConstruccionDetalleDto(r.Int64("ConstruccionProyectoId"),r.Int32("SedeId"),r.Text("Sede"),NI(r,"ClienteId"),r.NullableText("Cliente"),r.Text("Nombre"),r.Text("TipoObra"),r.Text("Ubicacion"),r.Date("FechaInicioPlanificada"),r.Date("FechaFinPlanificada"),D(r,"Presupuesto"),r.Text("Estado"),r.Int32("ResponsableUsuarioId"),r.Text("Responsable"),r.NullableText("Descripcion"),r.Date("FechaCreacion"),r.NullableDate("FechaModificacion"),[],[],[]);var acts=new List<ConstruccionActividadDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))acts.Add(new(r.Int64("ConstruccionActividadId"),r.Text("Nombre"),r.Int32("ResponsableUsuarioId"),r.Text("Responsable"),r.Date("FechaInicio"),r.Date("FechaFin"),D(r,"Presupuesto"),D(r,"PorcentajeAvance"),r.Text("Estado"),r.NullableText("Observacion"),D(r,"CostoReal")));var rec=new List<ConstruccionRecursoDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))rec.Add(new(r.Int64("ConstruccionRecursoId"),NL(r,"ConstruccionActividadId"),r.Text("Tipo"),r.Text("Descripcion"),D(r,"Cantidad"),r.Text("Unidad"),D(r,"CostoUnitario"),NI(r,"InventarioArticuloId"),r.NullableText("ArticuloCodigo"),NI(r,"MaquinariaEquipoId"),r.NullableText("MaquinariaCodigo"),r.Text("NombreUsuario"),r.Date("Fecha")));var av=new List<ConstruccionAvanceDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))av.Add(new(r.Int64("ConstruccionAvanceId"),r.Int64("ConstruccionActividadId"),r.Text("Actividad"),D(r,"PorcentajeAnterior"),D(r,"PorcentajeNuevo"),r.Text("Comentario"),r.NullableText("EvidenciaUrl"),r.Text("NombreUsuario"),r.Date("Fecha")));return x with{Actividad