 private async Task<long>Scalar(string p,AlcanceConstruccion a,CancellationToken ct,Action<SqlCommand>add){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,p);add(c);Scope(c,a);return Convert.ToInt64(await c.ExecuteScalarAsync(ct));}private static async Task<IReadOnlyList<CatalogoDto>>Next(SqlDataReader r,CancellationToken ct)=>await r.NextResultAsync(ct)?await Cats(r,ct):[];private static async Task<IReadOnlyList<CatalogoDto>>Cats(SqlDataReader r,CancellationToken ct){var x=new List<CatalogoDto>();while(await r.ReadAsync(ct))x.Add(new(r.Int32("Id"),r.Text("Nombre")));return x;}private static void Scope(SqlCommand c,AlcanceConstruccion a){c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=a.UsuarioId;c.Parameters.Add("@EsAdministrador",SqlDbType.Bit).Value=a.EsAdministrador;}private static SqlCommand P(SqlConnection c,string n)=>new(n,c){CommandType=CommandType.StoredProcedure};private static object Db(object?x)=>x??DBNull.Value;private static string?T(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();private static decimal D(SqlDataReader r,string n)=>r.GetDecimal(r.GetOrdinal(n));private static int?NI(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetInt32(i);}private static long?NL(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetInt64(i);}private static void S(SqlCommand c,string n,int z,string?x)=>c.Parameters.Add(n,SqlDbType.NVarChar,z).Value=Db(T(x));private static void Dec(SqlCommand c,string n,decimal v,byte scale,byte precision=18){var p=c.Parameters.Add(n,SqlDbType.Decimal);p.Precision=precision;p.Scale=scale;p.Value=v;}
